mapper.update:
UPDATE tbl_group_challenge_daily_result
   SET verdict_deduction_amount = verdict_deduction_amount + #{amount}
 WHERE id = #{resultId}

mapper.select:
SELECT MAX(r.challenge_date)
  FROM tbl_group_challenge_daily_result r
 WHERE r.group_id = #{groupId}
   AND r.challenge_date < #{today}
